(function(){const palette=["#00AEEF","#0047BB","#004C45","#FFB500","#FF7100","#9ADBE8","#66CBF4","#4D8FD6","#007A6E","#FFD466","#FFA64D","#C7EBF4","#BDBDBD"];const regionColors={MENAR:"#00AEEF",ESAR:"#0047BB",ECAR:"#004C45",WCAR:"#FFB500",LACR:"#FF7100",EAPR:"#9ADBE8",SAR:"#BDBDBD"};function getStableColor(name){if(!name)return"#00AEEF";let hash=0;for(let i=0;i<name.length;i++){hash=name.charCodeAt(i)+(Math.imul(hash,32)-hash)}return palette[Math.abs(hash)%palette.length]}function getRegionColor(code){return regionColors[code]||getStableColor(code)}function timeAxisLabel(value){return d3.timeFormat("%b %y")(new Date(value))}const countryAbbreviations={dem:"democratic",rep:"republic",s:"south",n:"north",barb:"barbuda",st:"saint"};const countryStopWords=new Set(["of","the","and","state","old","republic"]);const labelAliases={"social policy":"Social Policy","multi purpose":"Multi-Purpose Cash","multi purpose cash":"Multi-Purpose Cash","multipurpose cash":"Multi-Purpose Cash",mpc:"Multi-Purpose Cash","transfer to account":"Transfer to Account","cash over the counter":"Cash Over the Counter","pre paid card":"Pre-Paid Card","prepaid card":"Pre-Paid Card","atm card":"ATM Card",wash:"WASH"};function formatLabel(value){if(!value)return"";const key=String(value).trim().toLowerCase().replace(/[_-]+/g," ");if(labelAliases[key])return labelAliases[key];return key.replace(/\b\w/g,char=>char.toUpperCase())}function formatCountryName(name){if(!name)return"";return String(name).replace(/[-_]/g," ").replace(/\b\w/g,ch=>ch.toUpperCase())}function collapseTopRows(rows,maxBars=10,otherLabel="Other",mergeRest=null){if(!Array.isArray(rows)||rows.length<=maxBars)return rows;const top=rows.slice(0,maxBars);const rest=rows.slice(maxBars);const other=mergeRest?mergeRest(rest):{value:rest.reduce((sum,row)=>sum+(+row.value||0),0)};other.key=otherLabel;other.isOther=true;other.count=rest.length;top.push(other);return top}function countryKey(name){if(!name)return"";return String(name).normalize("NFKD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/&/g," and ").replace(/[^a-z0-9 ]/g," ").split(/\s+/).filter(Boolean).map(token=>countryAbbreviations[token]||token).filter(token=>!countryStopWords.has(token)).join(" ")}function initCountryFilter(options){const select=document.getElementById(options.selectId||"country-filter");if(!select||!options.dimension){return{populate:()=>{},apply:()=>{},get value(){return""}}}const dimension=options.dimension;const allLabel=select.dataset.allLabel||select.options[0]&&select.options[0].textContent||"All countries";let current="";try{current=window.localStorage.getItem("hopeCountry")||new URLSearchParams(window.location.search).get("country")||""}catch(error){current=""}function apply(){if(current)dimension.filter(current);else dimension.filterAll()}function render(values){select.innerHTML="";const all=document.createElement("option");all.value="";all.textContent=allLabel;select.appendChild(all);values.forEach(value=>{const option=document.createElement("option");option.value=value;option.textContent=formatCountryName(value);select.appendChild(option)});select.value=current}select.addEventListener("change",()=>{current=select.value;try{if(current)window.localStorage.setItem("hopeCountry",current);else window.localStorage.removeItem("hopeCountry");const url=new URL(window.location.href);if(current)url.searchParams.set("country",current);else url.searchParams.delete("country");window.history.replaceState({},"",url)}catch(error){}apply();if(options.onChange)options.onChange(current)});return{populate(rows){const values=Array.from(new Set((rows||[]).map(row=>row&&row.country_slug).filter(Boolean))).sort((a,b)=>formatCountryName(a).localeCompare(formatCountryName(b)));if(current&&!values.includes(current)){current="";try{window.localStorage.removeItem("hopeCountry")}catch(error){}}render(values)},apply:apply,get value(){return current}}}function setDataAsOf(rows){const el=document.getElementById("data-as-of");if(!el)return;const dates=(rows||[]).map(row=>row&&row.date instanceof Date?row.date:new Date(row&&row.date)).filter(date=>!Number.isNaN(date.getTime()));if(dates.length===0){el.textContent="—";return}const latest=new Date(Math.max(...dates.map(date=>date.getTime())));el.textContent=d3.timeFormat("%d %b %Y")(latest)}window.HopeChart={palette:palette,regionColors:regionColors,getStableColor:getStableColor,getRegionColor:getRegionColor,timeAxisLabel:timeAxisLabel,formatLabel:formatLabel,formatCountryName:formatCountryName,collapseTopRows:collapseTopRows,countryKey:countryKey,initCountryFilter:initCountryFilter,setDataAsOf:setDataAsOf}})();
